public class Main {
    public static void main(String[] args) {
        int[] a = {3, -2, 5, -1, 2, -6, 4};
        int best = a[0], current = a[0];
        for (int i = 1; i < a.length; i++) {
            current = Math.max(a[i], current + a[i]);
            best = Math.max(best, current);
        }
        System.out.println(best);
    }
}
